module sorted_train (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] n,\n    input [7:0] p [0:15],\n    output reg [7:0] result,\n    output reg done\n);\n    // State definitions\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] BUILD = 2'd1;\n    localparam [1:0] COMPUTE = 2'd2;\n    localparam [1:0] DONE_STATE = 2'd3;\n    \n    reg [1:0] state;\n    reg [7:0] j;\n    reg [7:0] k;\n    reg [7:0] current_len;\n    reg [7:0] max_len;\n    reg [7:0] inv [0:15];\n    integer i;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            j <= 8'd0;\n            k <= 8'd0;\n            current_len <= 8'd0;\n            max_len <= 8'd0;\n            for (i = 0; i < 16; i = i + 1) begin\n                inv[i] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start && n > 8'd0) begin\n                        state <= BUILD;\n                        j <= 8'd0;\n                    end\n                end\n                \n                BUILD: begin\n                    if (j < n) begin\n                        inv[p[j]-8'd1] <= j;\n                        j <= j + 8'd1;\n                    end else begin\n                        state <= COMPUTE;\n                        k <= 8'd1;\n                        current_len <= 8'd1;\n                        max_len <= 8'd1;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (k < n) begin\n                        if (inv[k] > inv[k-8'd1]) begin\n                            current_len <= current_len + 8'd1;\n                            if (current_len + 8'd1 > max_len) begin\n                                max_len <= current_len + 8'd1;\n                            end\n                        end else begin\n                            current_len <= 8'd1;\n                        end\n                        k <= k + 8'd1;\n                    end else begin\n                        result <= n - max_len;\n                        state <= DONE_STATE;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule